create or replace function public.schedule_schoolpro_admission_event(p_application uuid,p_type text,p_at timestamptz,p_location text,p_notes text) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions;e uuid;begin select * into a from public.schoolpro_admissions where id=p_application;if a.id is null then raise exception 'Application not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;insert into public.schoolpro_admission_events(application_id,event_type,scheduled_at,location,notes) values(a.id,p_type,p_at,p_location,p_notes) returning id into e;if a.guardian_email is not null then perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'admission_event','School admission '||p_type||' schedule',jsonb_build_object('applicant_name',a.applicant_name,'scheduled_at',p_at,'location',p_location,'notes',p_notes));end if;return e;end$$;
create or replace function public.issue_schoolpro_admission_offer(p_application uuid,p_letter text,p_expiry timestamptz,p_instructions text) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions;o public.schoolpro_admission_offers;begin select * into a from public.schoolpro_admissions where id=p_application;if a.id is null then raise exception 'Application not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;insert into public.schoolpro_admission_offers(application_id,offer_number,offered_class,letter_body,expires_at,acceptance_instructions,status) values(a.id,'OFR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),a.class_applied,p_letter,p_expiry,p_instructions,'offered') on conflict(application_id) do update set letter_body=excluded.letter_body,expires_at=excluded.expires_at,acceptance_instructions=excluded.acceptance_instructions,status='offered',issued_at=now() returning * into o;update public.schoolpro_admissions set status='admitted',reviewed_at=now(),reviewed_by=auth.uid() where id=a.id;if a.guardian_email is not null then perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'admission_offer','Admission offer for '||a.applicant_name,jsonb_build_object('applicant_name',a.applicant_name,'offer_number',o.offer_number,'offer_token',o.public_token));end if;return jsonb_build_object('offer_id',o.id,'offer_number',o.offer_number,'token',o.public_token);end$$;
revoke all on function public.schedule_schoolpro_admission_event(uuid,text,timestamptz,text,text),public.issue_schoolpro_admission_offer(uuid,text,timestamptz,text) from public,anon;grant execute on function public.schedule_schoolpro_admission_event(uuid,text,timestamptz,text,text),public.issue_schoolpro_admission_offer(uuid,text,timestamptz,text) to authenticated;